<?php require __DIR__.'/../includes/bootstrap.php';require_admin();require __DIR__.'/../includes/upload.php';$id=(int)($_GET['id']??0);$a=['title'=>'','slug'=>'','description'=>'','category'=>'','trigger_type'=>'','audio_url'=>'','cover_image'=>'','duration_seconds'=>0,'license_text'=>'','status'=>'draft'];if($pdo&&$id){$s=$pdo->prepare('SELECT * FROM audio_tracks WHERE id=?');$s->execute([$id]);$a=$s->fetch()?:$a;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['title','slug','description','category','trigger_type','license_text','status'] as $k)$a[$k]=trim($_POST[$k]??'');$a['duration_seconds']=max(0,(int)($_POST['duration_seconds']??0));try{if(!empty($_FILES['audio_file']['name']))$a['audio_url']=save_upload($_FILES['audio_file'],'audio');if(!empty($_FILES['cover_image']['name']))$a['cover_image']=save_upload($_FILES['cover_image'],'image');}catch(Throwable $e){$error=$e->getMessage();}if(!$error&&($a['title']===''||$a['slug']===''||$a['audio_url']===''||$a['license_text']===''))$error='Title, slug, audio file, and license are required.';elseif(!$error){try{if($id){$q=$pdo->prepare('UPDATE audio_tracks SET title=?,slug=?,description=?,category=?,trigger_type=?,audio_url=?,cover_image=?,duration_seconds=?,license_text=?,status=? WHERE id=?');$q->execute([$a['title'],$a['slug'],$a['description'],$a['category'],$a['trigger_type'],$a['audio_url'],$a['cover_image'],$a['duration_seconds'],$a['license_text'],$a['status'],$id]);}else{$q=$pdo->prepare('INSERT INTO audio_tracks(title,slug,description,category,trigger_type,audio_url,cover_image,duration_seconds,license_text,status) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$a['title'],$a['slug'],$a['description'],$a['category'],$a['trigger_type'],$a['audio_url'],$a['cover_image'],$a['duration_seconds'],$a['license_text'],$a['status']]);}header('Location: audio.php');exit;}catch(Throwable $e){$error='Unable to save audio.';}}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audio</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1><?=e($id?'Edit Audio':'New Audio')?></h1><?php if($error):?><p role="alert"><?=e($error)?></p><?php endif;?><form method="post" enctype="multipart/form-data" class="card"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><p><label>Title<input name="title" value="<?=e($a['title'])?>" required></label></p><p><label>Slug<input name="slug" value="<?=e($a['slug'])?>" required></label></p><p><label>Audio file<input type="file" name="audio_file" accept="audio/mpeg,audio/wav,audio/ogg" <?=$id?'':'required'?>></label></p><p><label>Cover image<input type="file" name="cover_image" accept="image/jpeg,image/png,image/webp"></label></p><p><label>Description<textarea name="description"><?=e($a['description']??'')?></textarea></label></p><p><label>License<textarea name="license_text" required><?=e($a['license_text']??'')?></textarea></label></p><p><label>Duration seconds<input type="number" name="duration_seconds" min="0" value="<?=$a['duration_seconds']?>"></label></p><p><label>Status<select name="status"><?php foreach(['draft','published','archived'] as $s):?><option <?=$a['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></label></p><button>Save audio</button> <a href="audio.php">Cancel</a></form></main></body></html>
